using Microsoft.AspNetCore.Mvc;using RaceDay.Mvc.Services;namespace RaceDay.Mvc.Controllers;public class HomeController(RaceApi api):Controller{public async Task<IActionResult> Index()=>View(await api.Get<List<RaceEvent>>("api/events")??new());public async Task<IActionResult> Details(int id){var e=await api.Get<EventDetails>("api/events/"+id);return e==null?NotFound():View(e);} [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Enter(int id,int categoryId,string? emergencyContactName,string? emergencyContactPhone){if(HttpContext.Session.GetString("role")!="Participant")return RedirectToAction("Login","Account");var r=await api.Send(HttpMethod.Post,"api/enrolments",new{categoryId,emergencyContactName,emergencyContactPhone});TempData["Notice"]=r.ok?"Entry confirmed in the system.":r.error;return RedirectToAction(nameof(Details),new{id});}public IActionResult Error()=>View();}